{
  "requirements": [
    {
      "text": "The library management system shall minimize energy consumption by using energy-efficient servers and infrastructure.",
      "kaos_level": "strategic",
      "rationale": "Reducing energy consumption aligns with sustainability goals and decreases the overall carbon footprint."
    },
    {
      "text": "The system shall provide an energy usage report for library operations at least quarterly.",
      "kaos_level": "tactical",
      "rationale": "Regular monitoring of energy usage helps identify areas for improvement in efficiency."
    },
    {
      "text": "The library management system shall enable digital notifications for overdue books to reduce paper waste.",
      "kaos_level": "operational",
      "rationale": "Utilizing digital communications supports sustainability by minimizing resource use."
    },
    {
      "text": "The system shall allow members to check the carbon footprint of each book based on its lifecycle impact.",
      "kaos_level": "tactical",
      "rationale": "Educating members about the carbon footprint raises awareness and promotes sustainable borrowing choices."
    },
    {
      "text": "The library management system shall implement a recycling program for damaged books, ensuring proper disposal.",
      "kaos_level": "operational",
      "rationale": "A recycling program reduces lifecycle resource impact and promotes sustainable practices."
    },
    {
      "text": "The system shall track the total energy savings achieved through digital operations compared to traditional methods.",
      "kaos_level": "tactical",
      "rationale": "Tracking energy savings offers measurable insights into the effectiveness of sustainability efforts."
    },
    {
      "text": "The library management system shall prioritize the acquisition of e-books to reduce physical resource consumption.",
      "kaos_level": "strategic",
      "rationale": "Acquiring more e-books supports resource efficiency and minimizes the carbon footprint associated with physical books."
    }
  ]
}
